source('R/stile.R')
salva_originale<-salva
salva<-function(mod,id,p,w=5.2,h=3.8)salva_originale(mod,id,p,w,if(id%in%c('F01','F02','F03','F07','F08','F09'))4.2 else h)
d<-leggi('spazio_v3.csv');xy<-as.matrix(d[c('x_m','y_m')]);z<-d$concentrazione;n<-nrow(d)
D<-as.matrix(dist(xy));A<-1*(D>0&D<=260);nv<-rowSums(A);W<-A/nv;v<-z-mean(z)
I<-function(q) n/sum(A)*sum(A*outer(q,q))/sum(q^2)
obs<-I(v);set.seed(20261109);B<-999;null<-replicate(B,I(sample(v)))
pperm<-(1+sum(null>=obs))/(B+1)
mapa<-function(data=d)ggplot(data,aes(x_m,y_m))+coord_equal()+scale_x_continuous(breaks=c(0,750,1500))+scale_y_continuous(breaks=c(0,750,1500))+labs(x='x (m)',y='y (m)')
cs<-function()scale_colour_gradientn(colours=c('#E1E9B2','#3C9F86','#254D67'),name='Concentrazione (u.a.)')
salva('M11','F01',mapa()+geom_point(aes(colour=concentrazione),size=3.5)+cs())
set.seed(11);dp<-d;dp$concentrazione<-sample(z)
salva('M11','F02',mapa(dp)+geom_point(aes(colour=concentrazione),size=3.5)+cs())
ed<-which(upper.tri(A)&A==1,arr.ind=TRUE);ee<-data.frame(x=xy[ed[,1],1],y=xy[ed[,1],2],xx=xy[ed[,2],1],yy=xy[ed[,2],2])
salva('M11','F03',mapa()+geom_segment(data=ee,aes(x=x,y=y,xend=xx,yend=yy),inherit.aes=FALSE,colour=geo[6],linewidth=.35)+geom_point(aes(colour=nv),size=3)+scale_colour_gradient(low=geo[2],high=geo[1],breaks=2:4,name='Numero di vicini'))
q<-data.frame(scarto=v,vicinato=as.vector(W%*%v))
salva('M11','F04',ggplot(q,aes(scarto,vicinato))+geom_hline(yintercept=0,colour=geo[6])+geom_vline(xintercept=0,colour=geo[6])+geom_point(colour=geo[1],size=2.3)+geom_smooth(method='lm',formula=y~x,se=FALSE,colour=geo[2])+labs(x='Scarto dal valore medio',y='Scarto medio dei vicini'))
salva('M11','F05',ggplot(data.frame(I=null),aes(I))+geom_histogram(binwidth=.04,boundary=0,fill=geo[1],colour=paper)+geom_vline(xintercept=obs,colour=geo[2],linewidth=1)+scale_x_continuous(breaks=c(-.2,0,.4,.8),labels=fmt)+labs(x='Indice di Moran',y='Permutazioni'))
pairs<-data.frame(h=D[upper.tri(D)],g=(.5*outer(z,z,'-')^2)[upper.tri(D)])
pairs$classe<-cut(pairs$h,c(0,300,600,1000,2500));vg<-aggregate(cbind(h,g)~classe,pairs,mean);vg$n<-as.integer(table(pairs$classe))
salva('M11','F06',ggplot(vg,aes(h,g))+geom_line(colour=geo[1],linewidth=.7)+geom_point(colour=geo[2],size=3)+scale_x_continuous(breaks=c(0,750,1500),limits=c(0,1700))+labs(x='Distanza media (m)',y='Semivarianza (u.a.²)'))
d$copertura<-factor(ifelse(d$y_m<=250,'Strada','Altri siti'),levels=c('Strada','Altri siti'))
salva('M11','F07',mapa()+geom_point(aes(colour=copertura),size=3.2)+scale_colour_manual(values=c(geo[2],'#B2C3C3')))
idw<-function(pos,xy,z,p=2){r<-sqrt(rowSums(sweep(xy,2,pos,'-')^2));if(any(r==0))return(mean(z[r==0]));w<-r^-p;sum(w*z)/sum(w)}
g<-expand.grid(x_m=seq(0,1750,length.out=45),y_m=seq(0,1750,length.out=45));g$z<-apply(as.matrix(g),1,idw,xy=xy,z=z)
salva('M11','F08',ggplot(g,aes(x_m,y_m,fill=z))+geom_raster()+geom_point(data=d,aes(x_m,y_m),inherit.aes=FALSE,size=.7,colour=ink)+coord_equal()+scale_x_continuous(breaks=c(0,750,1500))+scale_y_continuous(breaks=c(0,750,1500))+scale_fill_gradientn(colours=c('#E1E9B2','#3C9F86','#254D67'),name='Stima IDW (u.a.)')+labs(x='x (m)',y='y (m)'))
tr<-d$x_m<1250;pred<-apply(xy[!tr,],1,idw,xy=xy[tr,],z=z[tr]);err<-z[!tr]-pred
te<-d[!tr,];te$errore<-err
salva('M11','F09',mapa()+geom_point(data=d[tr,],colour='#B2C3C3',size=2)+geom_point(data=te,aes(colour=errore),size=3.5)+scale_colour_gradient2(low=geo[2],mid=paper,high=geo[1],midpoint=0,limits=c(-max(abs(err)),max(abs(err))),name='Osservato − previsto')+geom_vline(xintercept=1125,linetype=2,colour=geo[6]))
rr<-sqrt(rowSums(sweep(xy,2,c(900,900),'-')^2));pows<-1:3
ww<-sapply(pows,function(p){w<-rr^-p;w/sum(w)})
wd<-data.frame(distanza=rep(rr,3),peso=as.vector(ww),potenza=factor(rep(pows,each=n)))
salva('M11','F10',ggplot(wd,aes(distanza,peso,colour=potenza))+geom_line(linewidth=.7)+scale_colour_manual(values=geo[1:3],labels=c('p = 1','p = 2','p = 3'))+scale_y_continuous(labels=fmt,breaks=c(0,.15,.3))+scale_x_continuous(breaks=c(250,750,1250))+labs(x='Distanza dalla stima (m)',y='Peso normalizzato'))
# Confronti geometrici indipendenti dal piano locale sintetico.
p<-sf::st_as_sf(d,coords=c('lon','lat'),crs='OGC:CRS84');utm<-sf::st_transform(p,32632);back<-sf::st_coordinates(sf::st_transform(utm,'OGC:CRS84'))
verifica('Distanze: simmetria e diagonale',max(abs(D-t(D)))<1e-12&&all(diag(D)==0))
verifica('Reticolo: 112 legami non orientati',nrow(ee)==112&&sum(A)==224)
verifica('Normalizzazione per riga',all(nv>0)&&max(abs(rowSums(W)-1))<1e-12)
verifica('Moran: forma matriciale',abs(obs-n/sum(A)*as.numeric(t(v)%*%A%*%v)/sum(v^2))<1e-12)
verifica('Coppie: 2016 senza duplicati',sum(vg$n)==choose(n,2))
verifica('Pesi IDW positivi con somma uno',all(ww>0)&&max(abs(colSums(ww)-1))<1e-12)
verifica('IDW esatto nei siti privi di repliche',all(abs(vapply(1:n,function(i)idw(xy[i,],xy,z),0)-z)<1e-12))
verifica('IDW entro intervallo osservato',all(g$z>=min(z)&g$z<=max(z)))
verifica('Trasformazione CRS di ritorno',max(abs(back-as.matrix(d[c('lon','lat')])))<1e-7)
verifica('Partizione spaziale disgiunta',sum(tr)==40&&sum(!tr)==24&&all(is.finite(err)))
out<-'risultati/M11';dir.create(out,recursive=TRUE,showWarnings=FALSE)
write.csv(vg,file.path(out,'semivarianza.csv'),row.names=FALSE)
write.csv(te,file.path(out,'errori_est.csv'),row.names=FALSE)
write.csv(data.frame(I=null),file.path(out,'permutazioni.csv'),row.names=FALSE)
val<-list(I_binario=obs,I_normalizzato=as.numeric(t(v)%*%W%*%v)/sum(v^2),p_unilaterale=pperm,B=B,media=mean(z),media_strada=mean(z[d$y_m<=250]),idw_p1_p3=as.vector(t(ww)%*%z),MAE=mean(abs(err)),RMSE=sqrt(mean(err^2)),bias=mean(err),n_vicini=as.list(table(nv)))
jsonlite::write_json(val,file.path(out,'valori.json'),auto_unbox=TRUE,pretty=TRUE,digits=12)
print(val)
